class Solution {
public:
    vector<int> twoSum(vector<int>& nums, int target) {
        unordered_map<int,int> seen;              // 值 -> 下标
        for (int i = 0; i < (int)nums.size(); ++i) {
            auto it = seen.find(target - nums[i]);
            if (it != seen.end()) return {it->second, i};
            seen[nums[i]] = i;                    // 先查再存，避免同一个元素用两次
        }
        return {};
    }
};

class Solution {
public:
    vector<vector<int>> threeSum(vector<int>& a) {
        sort(a.begin(), a.end());
        vector<vector<int>> out;
        for (int i = 0; i + 2 < (int)a.size(); ++i) {
            if (i && a[i] == a[i-1]) continue;          // 固定值去重
            int l = i + 1, r = (int)a.size() - 1;
            while (l < r) {
                int s = a[i] + a[l] + a[r];
                if (s < 0) ++l;
                else if (s > 0) --r;
                else {
                    out.push_back({a[i], a[l], a[r]});
                    while (l < r && a[l] == a[l+1]) ++l; // 指针去重
                    while (l < r && a[r] == a[r-1]) --r;
                    ++l; --r;
                }
            }
        }
        return out;
    }
};

class Solution {
public:
    int maxArea(vector<int>& h) {
        int l = 0, r = (int)h.size() - 1, best = 0;
        while (l < r) {
            best = max(best, min(h[l], h[r]) * (r - l));
            if (h[l] < h[r]) ++l; else --r;   // 只有移动短边才有机会变大
        }
        return best;
    }
};

