class Solution {
public:
    void merge(vector<int>& a, int m, vector<int>& b, int n) {
        int i = m - 1, j = n - 1, k = m + n - 1;
        while (i >= 0 && j >= 0) a[k--] = (a[i] > b[j]) ? a[i--] : b[j--];
        while (j >= 0) a[k--] = b[j--];   // a 剩下的已经在正确位置
    }
};

class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        vector<int> last(128, -1);
        int l = 0, best = 0;
        for (int r = 0; r < (int)s.size(); ++r) {
            if (last[s[r]] >= l) l = last[s[r]] + 1;  // 只跳窗口内的重复
            last[s[r]] = r;
            best = max(best, r - l + 1);
        }
        return best;
    }
};

class Solution {
public:
    string longestPalindrome(string s) {
        int n = s.size(), bestL = 0, bestR = 0;
        auto grow = [&](int l, int r) {
            while (l >= 0 && r < n && s[l] == s[r]) { --l; ++r; }
            if (r - l - 1 > bestR - bestL + 1) { bestL = l + 1; bestR = r - 1; }
        };
        for (int c = 0; c < n; ++c) { grow(c, c); grow(c, c + 1); }
        return s.substr(bestL, bestR - bestL + 1);
    }
};

class Solution {
public:
    string addStrings(string a, string b) {
        string out;
        int i = a.size() - 1, j = b.size() - 1, carry = 0;
        while (i >= 0 || j >= 0 || carry) {
            int s = carry + (i >= 0 ? a[i--] - '0' : 0) + (j >= 0 ? b[j--] - '0' : 0);
            out.push_back(char('0' + s % 10));
            carry = s / 10;
        }
        reverse(out.begin(), out.end());
        return out;
    }
};

class Solution {
