        if (v.empty()) return "";
        for (int i = 0; i < (int)v[0].size(); ++i) {
            char c = v[0][i];
            for (int k = 1; k < (int)v.size(); ++k)
                if (i >= (int)v[k].size() || v[k][i] != c) return v[0].substr(0, i);
        }
        return v[0];
    }
};

class Solution {
public:
    ListNode* reverseList(ListNode* head) {
        ListNode* prev = nullptr;
        while (head) {
            ListNode* nxt = head->next;
            head->next = prev;
            prev = head;
            head = nxt;
        }
        return prev;
    }
};

class Solution {
public:
    ListNode* mergeTwoLists(ListNode* a, ListNode* b) {
        ListNode dummy(0), *t = &dummy;
        while (a && b) {
            if (a->val <= b->val) { t->next = a; a = a->next; }
            else { t->next = b; b = b->next; }
            t = t->next;
        }
        t->next = a ? a : b;
        return dummy.next;
    }
};

class Solution {
public:
    bool hasCycle(ListNode* head) {
        ListNode* slow = head, *fast = head;
        while (fast && fast->next) {
            slow = slow->next;
            fast = fast->next->next;
            if (slow == fast) return true;
        }
        return false;
    }
};

class Solution {
public:
    void reorderList(ListNode* head) {
        if (!head || !head->next) return;
        ListNode* slow = head, *fast = head;
        while (fast->next && fast->next->next) { slow = slow->next; fast = fast->next->next; }
        ListNode* mid = slow->next; slow->next = nullptr;      // 断成两段
        ListNode* b = nullptr;                                  // 反转后半段
        while (mid) { ListNode* n = mid->next; mid->next = b; b = mid; mid = n; }
        ListNode* a = head;
        while (b) {                                             // 交替合并
            ListNode* an = a->next, *bn = b->next;
            a->next = b; b->next = an;
            a = an; b = bn;
        }
    }
};

class LRUCache {
    int cap;
    list<pair<int,int>> lru;                                   // 头部最新
    unordered_map<int, list<pair<int,int>>::iterator> pos;
public:
    LRUCache(int capacity) : cap(capacity) {}
    int get(int key) {
        auto it = pos.find(key);
        if (it == pos.end()) return -1;
        lru.splice(lru.begin(), lru, it->second);              // 移到头部，迭代器保持有效
        return it->second->second;
    }
    void put(int key, int value) {
        auto it = pos.find(key);
        if (it != pos.end()) { it->second->second = value; lru.splice(lru.begin(), lru, it->second); return; }
        if ((int)lru.size() == cap) { pos.erase(lru.back().first); lru.pop_back(); }
        lru.emplace_front(key, value);
        pos[key] = lru.begin();
    }
};

