class Solution {
public:
    vector<int> maxSlidingWindow(vector<int>& a, int k) {
        deque<int> q;                       // 存下标，值单调递减
        vector<int> out;
        for (int i = 0; i < (int)a.size(); ++i) {
            while (!q.empty() && a[q.back()] <= a[i]) q.pop_back();
            q.push_back(i);
            if (q.front() <= i - k) q.pop_front();
            if (i >= k - 1) out.push_back(a[q.front()]);
        }
        return out;
    }
};

class Solution {
public:
    vector<int> inorderTraversal(TreeNode* root) {
        vector<int> out;
        stack<TreeNode*> st;
        TreeNode* cur = root;
        while (cur || !st.empty()) {
            while (cur) { st.push(cur); cur = cur->left; }
            cur = st.top(); st.pop();
            out.push_back(cur->val);
            cur = cur->right;
        }
        return out;
    }
};

class Solution {
public:
    vector<int> preorderTraversal(TreeNode* root) {
        vector<int> out;
        if (!root) return out;
        stack<TreeNode*> st;
        st.push(root);
        while (!st.empty()) {
            TreeNode* n = st.top(); st.pop();
            out.push_back(n->val);
            if (n->right) st.push(n->right);   // 先压右，左先出
            if (n->left) st.push(n->left);
        }
        return out;
    }
};

class Solution {
public:
    vector<int> postorderTraversal(TreeNode* root) {
        vector<int> out;
        stack<TreeNode*> st;
        TreeNode* cur = root, *last = nullptr;
        while (cur || !st.empty()) {
            while (cur) { st.push(cur); cur = cur->left; }
            TreeNode* n = st.top();
            if (n->right && n->right != last) { cur = n->right; continue; }
            out.push_back(n->val);
            st.pop();
            last = n;
        }
        return out;
    }
};

