class Solution {
public:
    TreeNode* invertTree(TreeNode* root) {
        if (!root) return nullptr;
        swap(root->left, root->right);
        invertTree(root->left);
        invertTree(root->right);
        return root;
    }
};

class Solution {
public:
    vector<vector<int>> levelOrder(TreeNode* root) {
        vector<vector<int>> out;
        if (!root) return out;
        queue<TreeNode*> q;
        q.push(root);
        while (!q.empty()) {
            int n = q.size();
            vector<int> row;
            while (n--) {
                TreeNode* t = q.front(); q.pop();
                row.push_back(t->val);
                if (t->left) q.push(t->left);
                if (t->right) q.push(t->right);
            }
            out.push_back(std::move(row));
        }
        return out;
    }
};

class Solution {
public:
    TreeNode* lowestCommonAncestor(TreeNode* r, TreeNode* p, TreeNode* q) {
        if (!r || r == p || r == q) return r;
        TreeNode* L = lowestCommonAncestor(r->left, p, q);
        TreeNode* R = lowestCommonAncestor(r->right, p, q);
        if (L && R) return r;          // 一边一个，当前即 LCA
        return L ? L : R;
    }
};

void quickSort(vector<int>& a, int l, int r) {
    if (l >= r) return;
    int p = a[l + rand() % (r - l + 1)], i = l, j = r;
    while (i <= j) {
        while (a[i] < p) ++i;
        while (a[j] > p) --j;
        if (i <= j) swap(a[i++], a[j--]);
    }
    quickSort(a, l, j);
    quickSort(a, i, r);
}
void mergeSort(vector<int>& a, vector<int>& tmp, int l, int r) {
    if (l >= r) return;
    int m = l + (r - l) / 2;
    mergeSort(a, tmp, l, m); mergeSort(a, tmp, m + 1, r);
    int i = l, j = m + 1, k = l;
    while (i <= m && j <= r) tmp[k++] = (a[i] <= a[j]) ? a[i++] : a[j++];
    while (i <= m) tmp[k++] = a[i++];
    while (j <= r) tmp[k++] = a[j++];
    for (int t = l; t <= r; ++t) a[t] = tmp[t];
}

class Solution {
public:
    int findKthLargest(vector<int>& a, int k) {
        int target = (int)a.size() - k, l = 0, r = (int)a.size() - 1;
        while (true) {
            int p = a[l + rand() % (r - l + 1)], i = l, j = r;
            while (i <= j) {
                while (a[i] < p) ++i;
                while (a[j] > p) --j;
                if (i <= j) swap(a[i++], a[j--]);
            }
            if (target <= j) r = j;
            else if (target >= i) l = i;
            else return a[target];
        }
    }
};

class Solution {
public:
    int search(vector<int>& a, int t) {
        int l = 0, r = (int)a.size();
        while (l < r) {
            int m = l + (r - l) / 2;
            if (a[m] == t) return m;
            if (a[m] < t) l = m + 1; else r = m;
        }
        return -1;
    }
};

class Solution {
public:
    int search(vector<int>& a, int t) {
        int l = 0, r = (int)a.size() - 1;
        while (l <= r) {
            int m = l + (r - l) / 2;
            if (a[m] == t) return m;
            if (a[l] <= a[m]) {                       // 左半有序
                if (a[l] <= t && t < a[m]) r = m - 1; else l = m + 1;
            } else {                                  // 右半有序
                if (a[m] < t && t <= a[r]) l = m + 1; else r = m - 1;
            }
        }
        return -1;
    }
};

class Solution {
public:
    int numIslands(vector<vector<char>>& g) {
        int n = g.size(), m = n ? g[0].size() : 0, cnt = 0;
        function<void(int,int)> flood = [&](int i, int j) {
            if (i < 0 || j < 0 || i >= n || j >= m || g[i][j] != '1') return;
            g[i][j] = '0';
            flood(i+1,j); flood(i-1,j); flood(i,j+1); flood(i,j-1);
        };
        for (int i = 0; i < n; ++i) for (int j = 0; j < m; ++j)
            if (g[i][j] == '1') { ++cnt; flood(i, j); }
        return cnt;
    }
};

class Solution {
public:
    int orangesRotting(vector<vector<int>>& g) {
        int n = g.size(), m = n ? g[0].size() : 0, fresh = 0, mins = 0;
        queue<pair<int,int>> q;
        for (int i = 0; i < n; ++i) for (int j = 0; j < m; ++j) {
            if (g[i][j] == 2) q.push({i,j});
            else if (g[i][j] == 1) ++fresh;
        }
        int dir[5] = {1,0,-1,0,1};
        while (!q.empty() && fresh) {
            int sz = q.size();
            while (sz--) {
                auto p = q.front(); q.pop();
                int x = p.first, y = p.second;
                for (int d = 0; d < 4; ++d) {
                    int nx = x + dir[d], ny = y + dir[d+1];
                    if (nx < 0 || ny < 0 || nx >= n || ny >= m || g[nx][ny] != 1) continue;
                    g[nx][ny] = 2; --fresh; q.push({nx,ny});
                }
            }
            ++mins;
        }
        return fresh ? -1 : mins;
    }
};

