template <class T>
class SharedPtr {
    T* ptr_ = nullptr;
    int* cnt_ = nullptr;
    void release() {
        if (cnt_ && --*cnt_ == 0) { delete ptr_; delete cnt_; }
        ptr_ = nullptr; cnt_ = nullptr;
    }
public:
    SharedPtr() = default;
    explicit SharedPtr(T* p) : ptr_(p), cnt_(p ? new int(1) : nullptr) {}
    SharedPtr(const SharedPtr& o) : ptr_(o.ptr_), cnt_(o.cnt_) { if (cnt_) ++*cnt_; }
    SharedPtr(SharedPtr&& o) noexcept : ptr_(o.ptr_), cnt_(o.cnt_) { o.ptr_ = nullptr; o.cnt_ = nullptr; }
    SharedPtr& operator=(SharedPtr o) { swap(o); return *this; }   // copy-and-swap 天然处理自赋值
    ~SharedPtr() { release(); }
    void swap(SharedPtr& o) noexcept { std::swap(ptr_, o.ptr_); std::swap(cnt_, o.cnt_); }
    T& operator*() const { return *ptr_; }
    T* operator->() const { return ptr_; }
    T* get() const { return ptr_; }
    long use_count() const { return cnt_ ? *cnt_ : 0; }
    explicit operator bool() const { return ptr_ != nullptr; }
};

class String {
    char* data_ = nullptr;
    size_t len_ = 0;
public:
    String(const char* s = "") {
        len_ = strlen(s);
        data_ = new char[len_ + 1];
        memcpy(data_, s, len_ + 1);
    }
    String(const String& o) : String(o.data_) {}                  // 委托构造，天然异常安全
    String(String&& o) noexcept : data_(o.data_), len_(o.len_) { o.data_ = nullptr; o.len_ = 0; }
    String& operator=(String o) { swap(o); return *this; }        // copy-and-swap
    ~String() { delete[] data_; }
    void swap(String& o) noexcept { std::swap(data_, o.data_); std::swap(len_, o.len_); }
    const char* c_str() const { return data_ ? data_ : ""; }
    size_t size() const { return len_; }
};

