template <class T>
class BlockingQueue {
    std::queue<T> q_;
    std::mutex m_;
    std::condition_variable cv_;
    bool closed_ = false;
public:
    void push(T v) {
        { std::lock_guard<std::mutex> lk(m_); if (closed_) return; q_.push(std::move(v)); }
        cv_.notify_one();
    }
    bool pop(T& out) {
        std::unique_lock<std::mutex> lk(m_);
        cv_.wait(lk, [&] { return closed_ || !q_.empty(); });   // 谓词防虚假唤醒
        if (q_.empty()) return false;
        out = std::move(q_.front()); q_.pop();
        return true;
    }
    void close() {
        { std::lock_guard<std::mutex> lk(m_); closed_ = true; }
        cv_.notify_all();
    }
};

void* my_memcpy(void* dst, const void* src, size_t n) {
    if (!dst || !src || n == 0) return dst;
    unsigned char* d = (unsigned char*)dst;
    const unsigned char* s = (const unsigned char*)src;
    if (d > s && d < s + n) {                       // 目标在后且重叠：倒着拷
        for (size_t i = n; i-- > 0;) d[i] = s[i];
    } else {
        for (size_t i = 0; i < n; ++i) d[i] = s[i];
    }
    return dst;
}
