template <class T, size_t N>
class ObjectPool {
    alignas(T) unsigned char buf_[N][sizeof(T)];
    T* free_[N] = {};
    size_t top_ = 0;
public:
    ObjectPool() { for (size_t i = 0; i < N; ++i) free_[i] = reinterpret_cast<T*>(buf_[i]); top_ = N; }
    template <class... A>
    T* acquire(A&&... a) {
        if (!top_) return nullptr;                 // 池满：由调用方决定扩容或等待
        T* p = free_[--top_];
        return new (p) T(std::forward<A>(a)...);    // placement new
    }
    void release(T* p) {
        if (!p) return;
        p->~T();                                   // 显式析构，避免资源泄漏
        free_[top_++] = p;
    }
};

class TimerMgr {
    struct Node { long long due; uint64_t seq; std::function<void()> fn; };
    struct Cmp { bool operator()(const Node& a, const Node& b) const { return a.due > b.due; } };
    std::priority_queue<Node, std::vector<Node>, Cmp> heap_;
    std::unordered_set<uint64_t> canceled_;
    uint64_t seq_ = 0;
public:
    uint64_t add(long long due, std::function<void()> fn) {
        uint64_t id = ++seq_;
        heap_.push({due, id, std::move(fn)});
        return id;
    }
    void cancel(uint64_t id) { canceled_.insert(id); }
    void tick(long long now) {
        while (!heap_.empty() && heap_.top().due <= now) {
            auto n = heap_.top(); heap_.pop();
            if (canceled_.erase(n.seq)) continue;     // 懒删除
            n.fn();
        }
    }
};

const long long STEP_US = 16667;          // 60 Hz
long long acc_ = 0, last_ = nowUs();
void frame() {
    long long now = nowUs();
    long long dt = now - last_;
    last_ = now;
    if (dt > 250000) dt = 250000;          // 切后台回来别一次追太多
    acc_ += dt;
    int steps = 0;
    while (acc_ >= STEP_US && steps < 5) { // 每帧最多追 5 步，防死亡螺旋
        update(STEP_US / 1e6);
        acc_ -= STEP_US;
        ++steps;
    }
    double alpha = (double)acc_ / STEP_US; // 渲染插值系数
    render(alpha);
}

struct AABB { float minX, minY, maxX, maxY; };
bool overlaps(const AABB& a, const AABB& b) {
    return a.minX <= b.maxX && b.minX <= a.maxX &&
           a.minY <= b.maxY && b.minY <= a.maxY;   // 相接算相交，按需改成 <
}
// forward 必须是单位向量；dot > 0 表示在前方，< 0 表示身后
bool inFront(const Vec2& pos, const Vec2& forward, const Vec2& target) {
    Vec2 d{ target.x - pos.x, target.y - pos.y };
    return d.x * forward.x + d.y * forward.y > 0.f;
}

enum class State { Idle, Move, Attack, Dead };
class FSM {
    State cur_ = State::Idle;
    bool can(State from, State to) const {
        if (from == State::Dead) return false;                 // Dead 不再转出
        if (to == State::Dead) return true;
        if (from == State::Attack) return to == State::Idle || to == State::Move;
        return true;
    }
public:
    bool to(State s) {
        if (s == cur_ || !can(cur_, s)) return false;
        exit(cur_); cur_ = s; enter(s);
        return true;
    }
    void update(float dt) {
        switch (cur_) {
            case State::Idle:   if (wantMove) to(State::Move); break;
            case State::Move:   if (!wantMove) to(State::Idle); break;
            case State::Attack: if (animDone) to(State::Idle); break;
            case State::Dead:   break;
        }
        tick(cur_, dt);
    }
};
